"""Содержание отчёта ЛР1 в виде блоков; числа — только из report/numbers.json и results.jsonl.

Блоки: ("h1", текст, с_новой_страницы), ("h2", текст), ("p", текст, жирное_начало), ("table", подпись, строки, ширины_см),
("fig", подпись, файл, ширина_см), ("figrow", [(подпись, файл, ширина_см), ...]), ("sources", [тексты]).
Один и тот же список блоков рендерится в Markdown и в docx.
"""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent


def load_numbers():
    return json.loads((ROOT / "report" / "numbers.json").read_text(encoding="utf-8"))


def first_attempt():
    """Первая серия эксперимента 3 (две записи упали из-за ошибки клиента): пересчёт из её results.jsonl."""
    import sys
    sys.path.insert(0, str(ROOT))
    import yaml
    from lr1.metrics import COMPUTE
    from lr1.tracking import read_results
    for d in sorted((ROOT / "runs").glob("*")):
        meta = json.loads((d / "metadata.json").read_text(encoding="utf-8"))
        if meta["series"] == "exp3_load" and meta["status"] == "completed":
            cfg = yaml.safe_load((d / "config.yaml").read_text(encoding="utf-8"))["experiment"]
            return meta["run_id"], COMPUTE["exp3"](read_results(d), cfg)
    raise SystemExit("нет первой серии exp3_load")


def fmt(x, nd=2):
    return f"{x:.{nd}f}".replace(".", ",")


