def to_markdown(bl):
    out = ["# ЛР1. Инференс и развёртывание языковой модели: от одного запроса к серверу под нагрузкой", ""]
    for blk in bl:
        k = blk[0]
        if k == "h1":
            out += [f"## {blk[1]}", ""]
        elif k == "h2":
            out += [f"### {blk[1]}", ""]
        elif k == "p":
            lead = f"**{blk[2].strip()}** " if blk[2] else ""
            out += [lead + blk[1], ""]
        elif k == "table":
            out += [f"**{blk[1]}**", ""]
            rows = blk[2]
            out.append("| " + " | ".join(str(c) for c in rows[0]) + " |")
            out.append("|" + "---|" * len(rows[0]))
            for r in rows[1:]:
                out.append("| " + " | ".join(str(c) for c in r) + " |")
            out.append("")
        elif k == "fig":
            out += [f"![{blk[1]}]({blk[2].replace('report/', '')})", "", f"*{blk[1]}*", ""]
        elif k == "figrow":
            for cap, path, _ in blk[1]:
                out += [f"![{cap}]({path.replace('report/', '')})", "", f"*{cap}*", ""]
        elif k == "sources":
            out += [f"{i}. {s}" for i, s in enumerate(blk[1], 1)] + [""]
    return "\n".join(out)
